import json
import numpy as np
from sympy import symbols, SOPform, And, Or, Not

# Each hexadecimal digit encodes four successive labels, each repeated four times.
encoded = (
    "2222a6aa00000c00"
    "2222a6aa00000c00"
    "2e2eaaaa0c0c0000"
    "2e2eaaaa0c0c0000"
)
labels = [
    (int(c, 16) >> shift) & 1
    for c in encoded
    for shift in (3, 2, 1, 0)
]
x = symbols("x0:8")
expression = SOPform(
    x,
    [[(i >> (7-j)) & 1 for j in range(8)]
     for i, label in enumerate(labels) if label]
)
terms = expression.args if expression.func is Or else (expression,)
assert len(terms) <= 34

arrays = {
    "w0": np.zeros((34, 10)),
    "b0": np.zeros(34),
    "w1": np.zeros((34, 34)),
    "b1": np.zeros(34),
    "w2": np.zeros((34, 34)),
    "b2": np.zeros(34),
    "w3": np.zeros((34, 34)),
    "b3": np.zeros(34),
    "out": np.zeros((3, 34)),
    "bias": np.zeros(3),
}

# A conjunction is exactly ReLU(sum(literals) - number_of_literals + 1).
for row, term in enumerate(terms):
    literals = term.args if term.func is And else (term,)
    positives = 0
    for literal in literals:
        negative = literal.func is Not
        variable = literal.args[0] if negative else literal
        column = x.index(variable)
        arrays["w0"][row, column] = -1 if negative else 1
        positives += not negative
    arrays["b0"][row] = 1 - positives
    for stage in (1, 2, 3):
        arrays[f"w{stage}"][row, row] = 1
    arrays["out"][1, row] = 1

arrays["bias"][0] = 0.5

entries = [
    (name, tuple(map(int, index)), float(array[tuple(index)]))
    for name, array in arrays.items()
    for index in np.argwhere(array != 0)
]

def accepted(result):
    if result is False:
        return False
    if isinstance(result, dict):
        if result.get("errors") or result.get("error"):
            return False
        for key in ("valid", "ok", "success"):
            if key in result and result[key] is False:
                return False
    return True

builders = [
    lambda: [{"op": "set", "tensor": n, "index": list(i), "value": v}
             for n, i, v in entries],
    lambda: [{"op": "set", "tensor": n, "indices": list(i), "value": v}
             for n, i, v in entries],
    lambda: [{"op": "set", "tensor": n,
              "index": int(np.ravel_multi_index(i, arrays[n].shape)), "value": v}
             for n, i, v in entries],
    lambda: [{"op": "set_tensor", "tensor": n, "values": a.tolist()}
             for n, a in arrays.items()],
    lambda: [{"op": "set", "tensor": n, "values": a.tolist()}
             for n, a in arrays.items()],
    lambda: [{"op": "replace", "tensor": n, "values": a.tolist()}
             for n, a in arrays.items()],
    lambda: [{"op": "set", "tensor": n, "value": a.tolist()}
             for n, a in arrays.items()],
]

for build in builders:
    sub = {"patch": build()}
    try:
        result = check_submission(sub)
    except Exception:
        continue
    if accepted(result):
        with open("/work/submission.json", "w") as f:
            json.dump(sub, f)
        break
else:
    raise RuntimeError("No tested numeric-patch representation passed format validation.")
